-- GENERATED FILE — do not hand-edit.
-- Source: tools/seed-gen (`cargo run` from that directory, output redirected here).
-- Realistic, varied data for exercising the Ashurbanipal DB browser: ten tables
-- spanning uuid/bigint-identity PKs, enums, numeric/real, arrays, inet, jsonb,
-- date/timestamptz, varchar(n), and NULLs throughout, plus single-column FKs
-- (including two distinct FK columns from one table to the same target) and one
-- deliberately empty table, across three schemas (public, other_schema, warehouse)
-- including cross-schema FKs. Idempotent (drops first) so it can be re-run against
-- a live dev db.

create extension if not exists pgcrypto;

-- A second schema with its own table, same name pattern as nothing else here —
-- the conformance fixture proving every catalog/data query is scoped to
-- current_schema() (spec/protocol.md §6) rather than enumerating every schema
-- on the connection: `decoy_items` must never appear in `/api/tables` (the
-- connection's `current_schema()` is `public`), and must be rejected as an
-- unknown table if requested directly.
drop schema if exists other_schema cascade;
create schema other_schema;
create table other_schema.decoy_items (
    id bigint generated always as identity primary key,
    label text not null
);

-- A third schema, `warehouse`, whose tables reference `public` (see write_schema());
-- created there, after `public`'s tables exist, but dropped up front like
-- other_schema — `cascade` covers the ordering either way.
drop schema if exists warehouse cascade;

-- New tables are dropped before the originals they reference — `cascade` handles
-- dependent constraints/views either way, but this keeps the drop order honest.
drop table if exists _conformance_meta cascade;
drop table if exists feature_flags cascade;
drop table if exists inventory_counts cascade;
drop table if exists inventory_locations cascade;
drop table if exists audit_log cascade;
drop table if exists payments cascade;
drop table if exists support_tickets cascade;
drop table if exists reviews cascade;
drop table if exists saved_reports cascade;
drop table if exists sessions cascade;
drop table if exists events cascade;
drop table if exists order_extra cascade;
drop table if exists orders cascade;
drop table if exists products cascade;
drop table if exists users cascade;
drop type if exists ticket_status cascade;
drop type if exists payment_status cascade;
drop type if exists order_status cascade;
drop type if exists product_category cascade;

create type order_status as enum ('pending', 'completed', 'cancelled', 'refunded');
create type product_category as enum ('electronics', 'books', 'home', 'toys', 'apparel');
create type ticket_status as enum ('open', 'in_progress', 'resolved', 'closed');
create type payment_status as enum ('pending', 'succeeded', 'failed', 'refunded');

create table users (
    id uuid primary key,
    email text not null unique,
    full_name text not null,
    age smallint,
    is_active boolean not null default true,
    login_count integer not null default 0,
    metadata jsonb not null default '{}',
    last_login_at timestamptz,
    created_at timestamptz not null default now()
);

create table orders (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references users(id),
    status order_status not null default 'pending',
    total_cents integer not null,
    discount_pct numeric(5,2),
    tags text[],
    line_items jsonb not null default '[]',
    created_at timestamptz not null default now()
);

-- 1:1 detail table: order_id is both this table's own PK and an FK into orders(id).
create table order_extra (
    order_id uuid primary key references orders(id),
    gift_message text,
    is_gift boolean not null default false,
    created_at timestamptz not null default now()
);

create table products (
    id bigint generated always as identity primary key,
    sku varchar(20) not null unique,
    name text not null,
    category product_category not null,
    price numeric(10,2) not null,
    weight_kg real,
    in_stock boolean not null default true,
    description text,
    created_on date not null default current_date
);

create table events (
    id bigint generated always as identity primary key,
    user_id uuid references users(id),
    event_type text not null,
    payload jsonb not null default '{}',
    ip_address inet,
    duration_ms integer,
    occurred_at timestamptz not null default now(),
    is_test boolean not null default false
);

create table sessions (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references users(id),
    device_type varchar(20) not null,
    user_agent text not null,
    ip_address inet,
    started_at timestamptz not null,
    ended_at timestamptz
);

create table reviews (
    id bigint generated always as identity primary key,
    user_id uuid not null references users(id),
    product_id bigint not null references products(id),
    order_id uuid references orders(id),
    rating smallint not null,
    title text,
    body text,
    is_verified_purchase boolean not null default false,
    created_at timestamptz not null default now()
);

create table support_tickets (
    id bigint generated always as identity primary key,
    user_id uuid not null references users(id),
    assigned_admin_id uuid references users(id),
    order_id uuid references orders(id),
    subject text not null,
    description text not null,
    status ticket_status not null default 'open',
    created_at timestamptz not null,
    resolved_at timestamptz
);

create table payments (
    id bigint generated always as identity primary key,
    order_id uuid not null references orders(id),
    processed_by_user_id uuid references users(id),
    related_event_id bigint references events(id),
    amount_cents integer not null,
    status payment_status not null default 'pending',
    gateway_response jsonb not null default '{}',
    created_at timestamptz not null
);

create table audit_log (
    id bigint generated always as identity primary key,
    actor_user_id uuid references users(id),
    session_id uuid references sessions(id),
    event_id bigint references events(id),
    action text not null,
    details jsonb not null default '{}',
    occurred_at timestamptz not null
);

-- Deliberately zero rows (see main()'s analyze block) — exercises the UI's
-- genuine empty-table state rather than the "stats not populated yet" one.
create table saved_reports (
    id bigint generated always as identity primary key,
    name text not null,
    is_public boolean not null default false,
    created_at timestamptz not null default now()
);

-- Composite primary key: inventory_counts' (warehouse_code, bin_code) FK
-- below references this pair together, never either column alone — the
-- conformance fixture for "composite FKs omit key/references metadata
-- entirely" (spec/protocol.md §5.4.1).
create table inventory_locations (
    warehouse_code varchar(10) not null,
    bin_code varchar(10) not null,
    label text,
    capacity integer not null default 100,
    primary key (warehouse_code, bin_code)
);

-- product_id is an ordinary single-column FK (contrast with the composite
-- one below); photo is the bytea fixture.
create table inventory_counts (
    id bigint generated always as identity primary key,
    warehouse_code varchar(10) not null,
    bin_code varchar(10) not null,
    product_id bigint references products(id),
    quantity integer not null,
    photo bytea,
    counted_at timestamptz not null default now(),
    foreign key (warehouse_code, bin_code) references inventory_locations(warehouse_code, bin_code)
);

-- Deliberately never ANALYZEd (see main()) — the empty-common-values and
-- -1-approx_rows conformance fixture.
create table feature_flags (
    id bigint generated always as identity primary key,
    key text not null unique,
    enabled boolean not null default true,
    rollout_pct smallint,
    created_at timestamptz not null default now()
);

-- Conformance sentinel (conformance/runner reads this when it isn't asked
-- to apply the seed itself) — see write_conformance_meta().
create table _conformance_meta (
    seed_version text not null,
    dialect text not null,
    checksum text not null,
    generated_at timestamptz not null default now()
);

comment on table users is 'Registered application users.';
comment on column users.metadata is 'Free-form per-user preferences and feature flags, stored as JSON.';

comment on table orders is 'Customer orders placed against the product catalog.';
comment on column orders.user_id is 'The user who placed this order.';
comment on column orders.discount_pct is 'Percentage discount applied at checkout, if any.';

comment on table sessions is 'Login sessions, one row per device/browser session.';

comment on table reviews is 'Product reviews left by users, optionally tied to a verified order.';

comment on table support_tickets is 'Customer support tickets, optionally assigned to a staff user.';
comment on column support_tickets.description is 'Full ticket body as submitted by the customer.';

comment on table _conformance_meta is 'Conformance-suite sentinel row; not part of the application schema.';

create schema warehouse;

create table warehouse.carriers (
    id bigint generated always as identity primary key,
    name text not null unique,
    contact_email text,
    is_active boolean not null default true
);

create table warehouse.shipments (
    id bigint generated always as identity primary key,
    order_id uuid not null references public.orders(id),
    carrier_id bigint references warehouse.carriers(id),
    tracking_number varchar(30) not null,
    status varchar(20) not null,
    shipped_at timestamptz not null,
    delivered_at timestamptz
);

create table warehouse.shipment_events (
    id bigint generated always as identity primary key,
    shipment_id bigint not null references warehouse.shipments(id),
    handled_by_user_id uuid references public.users(id),
    event_type varchar(30) not null,
    occurred_at timestamptz not null,
    notes text
);

comment on table warehouse.shipments is 'Outbound shipments fulfilling orders placed in the public schema.';




